const x=$json;
const op=x.operation;
const allowed=['get_product','get_products','get_variation','search_products','availability_check'];
const valid = allowed.includes(op) &&
  x.request_id && x.caller_context &&
  ['product_read','checkout_validation','cart_validation','sales'].includes(x.caller_context.purpose);
if(!valid) throw new Error('WF-11 invalid request contract');
return [{json:{
  request_id:String(x.request_id),
  operation:op,
  caller_context:x.caller_context,
  product_id:x.product_id ?? null,
  sku:x.sku ?? null,
  variation_id:x.variation_id ?? null,
  search:x.search ?? null,
  page:x.page ?? 1,
  per_page:Math.min(Number(x.per_page ?? 20),50)
}}];

const x=$json;
let gatewayOperation='get_product';
if(x.operation==='get_products'||x.operation==='search_products') gatewayOperation='get_products';
if(x.operation==='get_variation') gatewayOperation='get_variation';
if(x.operation==='availability_check') gatewayOperation='get_product';
return [{json:{...x,gateway_operation:gatewayOperation}}];

const r=$json;
if(r.error || r.success===false) {
  if(r.commerce_status==='unavailable' || r.source_of_truth==='kb_only') return [{json:{success:false, request_id:$node['Validate Request'].json.request_id, operation:$node['Validate Request'].json.operation, commerce_status:'unavailable', source:'kb', kb_fallback_allowed:true, fallback_required:true, reason:r.error_message || 'WooCommerce unavailable'}}];
  throw new Error(r.error_message || 'WooCommerce product read failed');
}
if(r.commerce_status==='unavailable' || r.source_of_truth==='kb_only') return [{json:{success:false, request_id:$node['Validate Request'].json.request_id, operation:$node['Validate Request'].json.operation, commerce_status:'unavailable', source:'kb', kb_fallback_allowed:true, fallback_required:true, reason:'WooCommerce unavailable'}}];
const p=r.product || r.data || r;
const clean={
  id:p.id ?? null,
  name:p.name ?? null,
  sku:p.sku ?? null,
  type:p.type ?? null,
  status:p.status ?? null,
  price:p.price ?? null,
  regular_price:p.regular_price ?? null,
  sale_price:p.sale_price ?? null,
  on_sale:p.on_sale ?? false,
  purchasable:p.purchasable ?? false,
  manage_stock:p.manage_stock ?? false,
  stock_quantity:p.stock_quantity ?? null,
  stock_status:p.stock_status ?? null,
  backorders_allowed:p.backorders_allowed ?? false,
  parent_id:p.parent_id ?? 0,
  attributes:p.attributes ?? [],
  variations:Array.isArray(p.variations)?p.variations:[],
  categories:Array.isArray(p.categories)?p.categories.map(c=>({id:c.id,name:c.name,slug:c.slug})):[],
  images:Array.isArray(p.images)?p.images.map(i=>({id:i.id,src:i.src,alt:i.alt})):[],
  permalink:p.permalink ?? null
};
const available = clean.purchasable === true &&
  clean.stock_status === 'instock' &&
  (clean.manage_stock !== true || clean.stock_quantity === null || Number(clean.stock_quantity) > 0);
return [{json:{
  success:true,
  request_id:$node['Validate Request'].json.request_id,
  operation:$node['Validate Request'].json.operation,
  product:clean,
  availability:{available,stock_status:clean.stock_status,stock_quantity:clean.stock_quantity},
  source:'woocommerce',
  verified_at:new Date().toISOString()
}}];

const r=$json;
const req=$node['Validate Request'].json;
const operation=req.operation;
const allowed=['get_product','get_products','get_variation','search_products'];
if(!allowed.includes(operation)) throw new Error('KB fallback is not allowed for this product operation');
// KB is informational fallback only. Do not synthesize live price, stock, sale status, or availability.
const supplied = r.kb_context ?? r.kb_result ?? null;
return [{json:{success:true,request_id:req.request_id,operation,source:'kb',commerce_status:'unavailable',kb_fallback:true,kb_context:supplied,live_fields_unavailable:['price','sale_price','stock_quantity','stock_status','purchasable','availability'],message:supplied ? null : 'KB retrieval context required from the configured RAG/Supabase retrieval path.'}}];
